/// <summary>
/// Resource statistic helper
/// </summary>
public final class NDXResourcesStatisticHelper
{
    Date                fromDate, toDate;
    boolean             dayInTimeValue;
    boolean             showUTimes;                            
    boolean             showTimeInSec;
    boolean             showTimeInMin;                         
    boolean             showTimeInStd;                         
    boolean             showTimeAsStr;                         

    Object              caller;
    str                 callername;
    ResResourceType     resourceType;                           

}

